/* ---------------------------------- HANDOVER DATA MODEL ---------------------------------- */

function buildHandoverData(p) {
  const secondary = p.severity === "critical" ? "Acute kidney injury"
    : p.severity === "guarded" ? "Electrolyte imbalance, monitoring" : "No active secondary issues";
  return {
    activeProblems: [p.dx, secondary].filter(Boolean),
    clinicalStatus: p.severity === "critical" ? "Critically ill, on vasopressor support"
      : p.severity === "guarded" ? "Stable but guarded, requires ongoing monitoring"
      : "Stable, improving, step-down candidate",
    neuro: p.severity === "critical" ? "GCS E2 V2 M4, sedated" : p.vent ? "GCS E3 V4 M6, sedation lightened" : "Alert and oriented, GCS 15",
    respiratoryStatus: p.vent ? "Mechanically ventilated" : "Spontaneously breathing, room air",
    ventilator: p.vent ? "PC mode | FiO2 40% | PEEP 8\nRR 20 | PIP 22" : "",
    oxygenSupport: p.vent ? "N/A, mechanically ventilated" : "Room air",
    hemodynamics: p.severity === "critical" ? "MAP 62 mmHg on vasopressors" : "MAP >65 mmHg, hemodynamically stable, normal sinus rhythm",
    vasopressors: p.pressor ? "Noradrenaline 0.08 mcg/kg/min" : "None",
    renal: p.dialysis ? "Oliguric, AKI, creatinine rising" : "Urine output adequate, creatinine at or near baseline",
    crrt: p.dialysis ? "CVVHDF started this admission, net UF per target" : "",
    infectionStatus: p.severity === "critical" ? "Septic shock, on antibiotics" : p.severity === "guarded" ? "Suspected infection, monitoring" : "No active infection",
    labsList: [
      { name: "WBC", value: "15.2", flag: "high" }, { name: "Hb", value: "9.1", flag: null },
      { name: "Platelets", value: "120", flag: "low" }, { name: "Na", value: "134", flag: null },
      { name: "K", value: "4.8", flag: null }, { name: "Cr", value: "2.1", flag: "high" },
      { name: "Lactate", value: "2.8", flag: "high" },
    ],
    abg: { ph: "7.32", paco2: "38", pao2: "90", hco3: "19" },
    microbiology: p.severity === "critical" ? "Blood culture: Gram-negative rods\nSputum culture: Pending" : "No active cultures pending",
    imaging: "CXR: Bilateral infiltrates, improved",
    antibiotics: p.severity === "critical" ? "Piperacillin/Tazobactam 4.5g IV q6h\nVancomycin 1g IV q12h" : "None currently",
    medicationsList: [
      p.pressor && "Noradrenaline", p.severity === "critical" && "Hydrocortisone",
      "Pantoprazole", "Paracetamol",
    ].filter(Boolean),
    procedures: p.dialysis ? "CRRT catheter inserted this admission" : "Central and arterial line placement on admission",
    linesDevices: [
      p.vent && "Endotracheal tube",
      "Central venous catheter",
      "Arterial line",
      "Urinary catheter",
      p.dialysis && "CRRT dialysis catheter",
    ].filter(Boolean).join(", "),
    linesDevicesList: [
      p.vent && "ETT", "CVC", "Arterial line", p.vent && "OGT", "Urinary catheter", p.dialysis && "Dialysis catheter",
    ].filter(Boolean),
    nutrition: p.vent ? "Enteral feeding via OGT\n40 mL/hr, tolerating" : "Oral diet, tolerating well",
    pendingInvestigations: "Repeat labs and blood gas as scheduled; chase pending culture results",
    eventsList: [
      p.dialysis && "Started CVVHDF due to worsening renal function",
      p.pressor && "Increased vasopressor requirement overnight",
      p.severity === "critical" && "Lactate increased to 2.8",
      p.vent && "Ventilator settings adjusted",
      "No new bleeding or arrhythmias",
      "Family updated",
    ].filter(Boolean),
    eventsToday: "Reviewed on morning round; no new acute events since last handover",
    assessment: `${p.dx}.${p.pressor ? " Hemodynamically unstable on vasopressors." : ""}${p.vent ? " Respiratory status guarded on mechanical ventilation." : ""}${p.dialysis ? " AKI requiring CRRT." : ""} Close monitoring required.`,
    plan: [
      p.pressor && "Titrate vasopressor to maintain MAP ≥65",
      p.vent && "Wean ventilator as tolerated",
      p.dialysis && "Reassess CRRT requirement at next review",
      "Repeat ABG in 4 hours",
      "Monitor lactate and urine output",
      "Continue antibiotics and follow cultures",
    ].filter(Boolean),
    nextShiftTasks: [
      "Repeat CBC, renal profile, and liver tests at 12:00 PM",
      "Follow blood culture sensitivity",
      "Review CXR tomorrow",
      "Dietitian review",
      "Physiotherapy",
    ],
    codeStatus: p.codeStatus || "Full code",
    familyUpdated: p.severity === "critical" ? "Yes – Yesterday, 10:00 PM" : "Yes – Today",
    goalsOfCare: p.severity === "critical" ? "Planned for today with family" : "Not required at this time",
  };
}


const SHIFTS = ["Morning", "Evening", "Night"];
function currentShift() {
  const h = new Date().getHours();
  if (h >= 7 && h < 15) return "Morning";
  if (h >= 15 && h < 23) return "Evening";
  return "Night";
}


