function verificationFor(relation) { return (relation === "assisted" || relation === "supervised") ? "Pending Verification" : "Not Required"; }

function dueDateFor(label) {
  const now = new Date();
  const d = new Date(now);
  if (label === "Now") return d;
  if (label === "+2h") { d.setHours(d.getHours() + 2); return d; }
  if (label === "+4h") { d.setHours(d.getHours() + 4); return d; }
  if (label === "Tonight") { d.setHours(20, 0, 0, 0); if (d < now) d.setDate(d.getDate() + 1); return d; }
  if (label === "Tomorrow AM") { d.setDate(d.getDate() + 1); d.setHours(8, 0, 0, 0); return d; }
  return d;
}
function isTaskOverdue(ts) {
  return (ts.status === "pending" || ts.status === "in_progress") && ts.dueDate && new Date(ts.dueDate) < new Date();
}

