// Doctor's display role for a procedure, from the perspective of doctor id `viewerId`
function roleForDoctor(pr, viewerId) {
  if (pr.primaryOperatorId === viewerId) return "Primary Operator";
  if ((pr.assistantIds || []).includes(viewerId)) return "Assisted";
  if (pr.supervisorId === viewerId) return "Supervisor";
  return null;
}
function isCreditedTo(pr, viewerId) { return roleForDoctor(pr, viewerId) !== null; }

