function getPatientPermission(p, groups) {
  if (p.doctor === "You") return "owner";
  const g = groups.find(gr => gr.patientIds.includes(p.id));
  if (g) return g.permissions["you"] || "view";
  return "view";
}
function canManageStatus(permission) { return permission === "owner" || permission === "admin"; }

