const STATUS_COLORS = { grey: "#8A97AC", green: BRAND.success, blue: BRAND.teal, orange: BRAND.warning, red: BRAND.critical };

function TrendBars({ values, t, unit, reverseGood }) {
  const max = Math.max(...values), min = Math.min(...values);
  const last = values[values.length - 1], prev = values[values.length - 2];
  const up = last > prev;
  const improving = reverseGood ? !up : up;
  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: 4, height: 40 }}>
      {values.map((v, i) => {
        const h = 10 + ((v - min) / Math.max(0.001, max - min)) * 30;
        return <div key={i} style={{
          width: 7, height: h, borderRadius: 3,
          background: i === values.length - 1 ? (improving ? BRAND.success : BRAND.critical) : t.border,
        }} />;
      })}
    </div>
  );
}

