const NO_SAME_AS_PREVIOUS = ["procedures", "meds"];

function timeAgo(iso) {
  if (!iso) return null;
  const mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins} min ago`;
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return `${hrs} hr${hrs === 1 ? "" : "s"} ago`;
  return new Date(iso).toLocaleDateString();
}

function SectionQuickActions({ t, dark, sectionKey, sectionTitle, patientId, permission, meta, onUpdate, onUpload, onSameAsPrevious }) {
  const canEdit = permission !== "view";
  const status = meta && meta.lastUpdatedAt ? "Completed" : "Incomplete";
  const statusColor = status === "Completed" ? BRAND.success : BRAND.warning;
  const allowSameAsPrevious = !NO_SAME_AS_PREVIOUS.includes(sectionKey);

  return (
    <div style={{ marginBottom: 10 }}>
      <div style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif", lineHeight: 1.6, marginBottom: 8 }}>
        {meta && meta.lastUpdatedAt ? (
          <>Last updated {timeAgo(meta.lastUpdatedAt)} by {meta.lastUpdatedBy}</>
        ) : "Not yet updated this shift"}
        {meta && meta.files && meta.files.length > 0 && <> · {meta.files.length} attached file{meta.files.length === 1 ? "" : "s"}</>}
        {" · "}<span style={{ color: statusColor, fontWeight: 700 }}>Status: {status}</span>
      </div>
      {canEdit && (
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          <button onClick={onUpdate} style={{
            display: "flex", alignItems: "center", gap: 5, border: "none", background: BRAND.teal, color: "#fff",
            borderRadius: 10, padding: "7px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer",
          }}><Pencil size={11} /> Update</button>
          <button onClick={onUpload} style={{
            display: "flex", alignItems: "center", gap: 5, border: `1.5px solid ${BRAND.navy}`, background: "transparent", color: BRAND.navy,
            borderRadius: 10, padding: "7px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer",
          }}><Upload size={11} /> Upload File</button>
          {allowSameAsPrevious && (
            <button onClick={onSameAsPrevious} style={{
              display: "flex", alignItems: "center", gap: 5, border: "none", background: t.surface2, color: t.text,
              borderRadius: 10, padding: "7px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer",
            }}><Copy size={11} /> Same as Previous</button>
          )}
        </div>
      )}
    </div>
  );
}

