const QUICK_STATUS_CHIPS = ["Stable", "Improved", "Worsened", "Unchanged", "New finding"];

function SectionUpdateModal({ t, dark, sectionKey, sectionTitle, patientName, currentSummary, sameAsPrevious, onClose, onSave }) {
  const [statusChip, setStatusChip] = useState(sameAsPrevious ? "Unchanged" : "Stable");
  const [note, setNote] = useState(sameAsPrevious ? currentSummary : "");
  const [savedAt, setSavedAt] = useState(null);
  const saveTimer = useRef(null);

  const handleNoteChange = (val) => {
    setNote(val);
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => setSavedAt(new Date()), 700);
  };

  const changed = note.trim() !== "" && note.trim() !== (currentSummary || "").trim();

  return (
    <ModalShell t={t} onClose={onClose} title={sameAsPrevious ? `Same as Previous — ${sectionTitle}` : `Update ${sectionTitle}`} icon={Pencil} tall>
      {sameAsPrevious && (
        <div style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: 12, borderRadius: 12, background: t.accentSoft, marginBottom: 14 }}>
          <Copy size={15} color={t.accent} style={{ flexShrink: 0, marginTop: 1 }} />
          <div style={{ fontSize: 12, color: t.text, fontFamily: "Inter, sans-serif" }}>Copied from the latest approved {sectionTitle.toLowerCase()} entry for {patientName}. Review before saving.</div>
        </div>
      )}
      {!sameAsPrevious && currentSummary && (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 10.5, fontWeight: 700, color: t.muted, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 4 }}>Latest saved data</div>
          <div style={{ fontSize: 12.5, color: t.text, fontFamily: "Inter, sans-serif", background: t.surface2, borderRadius: 12, padding: "10px 12px" }}>{currentSummary}</div>
        </div>
      )}

      <Field label="Quick status" t={t}>
        {QUICK_STATUS_CHIPS.map(c => (
          <Chip key={c} label={c} active={statusChip === c} onClick={() => setStatusChip(c)} t={t}
            color={c === "Worsened" || c === "New finding" ? BRAND.warning : undefined} />
        ))}
      </Field>

      <div style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif", marginBottom: 6, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.4 }}>
        {sameAsPrevious ? "Copied entry (edit as needed)" : "Note"}
      </div>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 8, background: changed ? t.accentSoft : t.surface2, border: changed ? `1.5px solid ${t.accent}` : "none", borderRadius: 12, padding: "10px 14px", marginBottom: 6 }}>
        <textarea value={note} onChange={e => handleNoteChange(e.target.value)} placeholder="Quick note — voice or type"
          style={{ flex: 1, minHeight: 70, border: "none", outline: "none", background: "transparent", fontSize: 13.5, color: t.text, fontFamily: "Inter, sans-serif", resize: "vertical" }} />
        <Mic size={16} color={t.accent} style={{ flexShrink: 0, marginTop: 2 }} />
      </div>
      {changed && <div style={{ fontSize: 10.5, color: t.accent, fontWeight: 700, marginBottom: 10 }}>Changed from previous value</div>}
      <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 16 }}>
        {savedAt ? (
          <span style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif", display: "flex", alignItems: "center", gap: 3 }}><CheckCircle2 size={11} color={t.accent} /> Draft auto-saved</span>
        ) : (
          <span style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif" }}>Drafts save automatically as you type</span>
        )}
      </div>

      <div style={{ display: "flex", gap: 10 }}>
        <button onClick={onClose} style={{ flex: 1, padding: 13, borderRadius: 14, border: `1.5px solid ${t.border}`, background: "transparent", color: t.text, fontWeight: 700, fontFamily: "Manrope, sans-serif", cursor: "pointer" }}>Cancel</button>
        <button onClick={() => onSave({ statusChip, note, sameAsPrevious })} style={{ flex: 1, padding: 13, borderRadius: 14, border: "none", background: BRAND.teal, color: "#fff", fontWeight: 700, fontFamily: "Manrope, sans-serif", cursor: "pointer" }}>Save</button>
      </div>
    </ModalShell>
  );
}

