/* ---------------------------------- TIMELINE ---------------------------------- */

const TL_ICON = { lab: FlaskConical, med: Pill, round: Stethoscope, imaging: Camera, procedure: ShieldAlert, admission: UserPlus, plan: ClipboardCheck, followup: ClipboardList, update: Pencil };

function Timeline({ p, t, onBack, approvedPlan, approvedFollowup, patientProcedures, sectionMeta, patientMedications }) {
  let lastDay = null;
  let events = timelineEvents;
  if (patientMedications && patientMedications.length) {
    const medEvents = [];
    patientMedications.forEach(m => {
      medEvents.push({ t: new Date(m.startDateTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), d: "Today", type: "med", label: `${m.name} started — ${m.dose} ${m.route} ${m.frequency}` });
      (m.editHistory || []).forEach(h => medEvents.push({ t: h.dateTime, d: "Today", type: "med", label: `${m.name} — ${h.action}: ${h.previousValue} → ${h.newValue} (${h.doctor})` }));
    });
    if (medEvents.length) events = [...medEvents, ...events];
  }
  if (sectionMeta) {
    const sectionEvents = [];
    Object.entries(sectionMeta).forEach(([key, meta]) => {
      (meta.history || []).forEach(h => {
        const def = CARD_DEFS.find(c => c.key === key);
        sectionEvents.push({
          t: h.time, d: "Today", type: "update",
          label: `${def ? def.title : key} updated${h.sameAsPrevious ? " (copied from previous)" : ""} — ${h.field}${h.note ? `: ${h.note}` : ""} · ${h.doctor}`,
        });
      });
    });
    if (sectionEvents.length) events = [...sectionEvents, ...events];
  }
  if (patientProcedures && patientProcedures.length) {
    events = [
      ...patientProcedures.map(pr => ({
        t: new Date(pr.dateTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), d: "Today", type: "procedure",
        label: `${pr.type} — performed by ${pr.primaryOperatorName || pr.externalTeam || "external team"}, ${pr.outcome}${pr.verificationStatus === "Pending Verification" ? " (pending supervisor verification)" : ""}`,
      })),
      ...events,
    ];
  }
  if (approvedFollowup) {
    events = [{
      t: approvedFollowup.time || "Just now", d: "Today", type: "followup",
      label: `Daily Follow-up approved — ${approvedFollowup.overallStatus} (${approvedFollowup.sectionsCompleted}/${approvedFollowup.totalSections} sections)${approvedFollowup.aiAccepted.length ? `, ${approvedFollowup.aiAccepted.length} AI plan items accepted` : ""}`,
    }, ...events];
  }
  if (approvedPlan) {
    events = [{
      t: "Just now", d: "Today", type: "plan",
      label: `Today's Plan approved — ${approvedPlan.checklist.length} AI recommendation${approvedPlan.checklist.length === 1 ? "" : "s"}${approvedPlan.manualText && approvedPlan.manualText.trim() ? " + physician's manual plan" : ""}`,
    }, ...events];
  }
  return (
    <div style={{ padding: "16px 14px 40px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
        <IconBtn icon={ChevronLeft} onClick={onBack} t={t} />
        <div>
          <div style={{ fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 16, color: t.text }}>Timeline</div>
          <div style={{ fontSize: 12, color: t.muted, fontFamily: "Inter, sans-serif" }}>{p.name} · {p.bed}</div>
        </div>
      </div>
      <div style={{ position: "relative", paddingLeft: 6 }}>
        <div style={{ position: "absolute", left: 20, top: 6, bottom: 6, width: 2, background: t.border }} />
        {events.map((ev, i) => {
          const showDay = ev.d !== lastDay; lastDay = ev.d;
          const Icon = TL_ICON[ev.type] || Activity;
          return (
            <div key={i}>
              {showDay && <div style={{ fontSize: 11.5, fontWeight: 700, color: t.muted, margin: "14px 0 8px 40px", fontFamily: "Inter, sans-serif", textTransform: "uppercase", letterSpacing: 0.5 }}>{ev.d}</div>}
              <div style={{ display: "flex", gap: 12, marginBottom: 14 }}>
                <div style={{
                  width: 40, height: 40, borderRadius: "50%", background: t.accentSoft, display: "flex",
                  alignItems: "center", justifyContent: "center", flexShrink: 0, zIndex: 1, border: `2px solid ${t.bg}`,
                }}>
                  <Icon size={16} color={t.accent} />
                </div>
                <div style={{ flex: 1, background: t.surface, border: `1px solid ${t.border}`, borderRadius: 14, padding: "10px 13px" }}>
                  <div style={{ fontSize: 11, color: t.muted, fontFamily: "'JetBrains Mono', monospace", marginBottom: 3 }}>{ev.t}</div>
                  <div style={{ fontSize: 13, color: t.text, fontFamily: "Inter, sans-serif" }}>{ev.label}</div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

