function GroupActivityModal({ t, group, patients, onClose }) {
  const entries = [
    { user: "Dr. Rami Haddad", action: "Updated hemodynamics", patient: patients.find(p => p.id === group.patientIds[0])?.name || "—", from: "MAP 62", to: "MAP 68", when: "07:40 Today", source: "Manual entry" },
    { user: "Nurse Amina Yusuf", action: "Added clinical event", patient: patients.find(p => p.id === group.patientIds[1])?.name || "—", from: "—", to: "Dressing changed, no issues", when: "08:10 Today", source: "Manual entry" },
    { user: "Dr. Sarah Nassar", action: "Added member", patient: "—", from: "—", to: "Dr. Layla Osei added to group", when: "Yesterday", source: "Group settings" },
  ];
  return (
    <ModalShell t={t} onClose={onClose} title="Group Activity" icon={History} tall>
      {entries.map((e, i) => (
        <div key={i} style={{ padding: "12px 0", borderBottom: i < entries.length - 1 ? `1px solid ${t.border}` : "none" }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: t.text, fontFamily: "Inter, sans-serif", marginBottom: 3 }}>{e.action} {e.patient !== "—" && `— ${e.patient}`}</div>
          {e.from !== "—" && (
            <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, fontFamily: "'JetBrains Mono', monospace", marginBottom: 3 }}>
              <span style={{ color: t.muted, textDecoration: "line-through" }}>{e.from}</span>
              <ChevronRight size={12} color={t.muted} />
              <span style={{ color: t.accent, fontWeight: 700 }}>{e.to}</span>
            </div>
          )}
          {e.from === "—" && <div style={{ fontSize: 12.5, color: t.text, fontFamily: "Inter, sans-serif", marginBottom: 3 }}>{e.to}</div>}
          <div style={{ fontSize: 11, color: t.muted, fontFamily: "Inter, sans-serif" }}>{e.user} · {e.when} · {e.source}</div>
        </div>
      ))}
    </ModalShell>
  );
}

/* ---------------------------------- GROUP CHAT ---------------------------------- */

function MessageBubble({ msg, t, dark, patients, isMe, onOpenUpdate, onOpenFiles, onReply, onStar }) {
  const [showActions, setShowActions] = useState(false);
  const m = memberById(msg.memberId);

  if (msg.type === "update") {
    const p = patients.find(pt => pt.id === msg.patientId);
    return (
      <div style={{
        display: "flex", alignItems: "flex-start", gap: 9, background: t.accentSoft, borderRadius: 14,
        padding: "10px 12px", margin: "8px 0", border: `1px solid ${t.accent}33`,
      }}>
        <div style={{ width: 22, height: 22, borderRadius: 7, background: BRAND.white, border: `1px solid ${t.border}`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginTop: 1 }}>
          <img src={LOGO_ICON} alt="" style={{ height: 11 }} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12.5, color: t.text, fontFamily: "Inter, sans-serif" }}>
            <strong>{msg.by}</strong> added a new {msg.updateType.toLowerCase()} update for <strong>{p ? `${p.name}, ${p.bed}` : "a patient"}</strong>.
          </div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 4 }}>
            <span style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif" }}>{msg.time}</span>
            <button onClick={() => onOpenUpdate(p)} style={{ border: "none", background: "none", color: t.accent, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>View →</button>
          </div>
        </div>
      </div>
    );
  }

  if (msg.type === "file") {
    const meta = FILE_TYPE_ICON[msg.fileType] || FILE_TYPE_ICON.pdf;
    return (
      <div style={{
        display: "flex", alignItems: "flex-start", gap: 9, background: t.surface2, borderRadius: 14,
        padding: "10px 12px", margin: "8px 0", border: `1px solid ${t.border}`,
      }}>
        <div style={{ width: 22, height: 22, borderRadius: 7, background: meta.c + "1E", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginTop: 1 }}>
          <meta.icon size={12} color={meta.c} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12.5, color: t.text, fontFamily: "Inter, sans-serif" }}>
            <strong>{msg.by}</strong> {msg.action === "replaced" ? "updated" : "uploaded"} a file: <strong>{msg.fileName}</strong>{msg.action === "replaced" ? ` (v${msg.version})` : ""}
          </div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 4 }}>
            <span style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif" }}>{msg.time}</span>
            <button onClick={onOpenFiles} style={{ border: "none", background: "none", color: t.accent, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>Open Files →</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", justifyContent: isMe ? "flex-end" : "flex-start", margin: "5px 0" }}>
      {!isMe && <MemberAvatar m={m} size={28} t={t} />}
      <div style={{ maxWidth: "72%", marginLeft: isMe ? 0 : 8, marginRight: isMe ? 0 : 0 }}>
        {!isMe && <div style={{ fontSize: 10.5, fontWeight: 700, color: t.accent, marginBottom: 2, fontFamily: "Inter, sans-serif" }}>{m ? m.name : "Unknown"}</div>}
        <div onClick={() => setShowActions(s => !s)} style={{
          background: isMe ? t.accent : t.surface, color: isMe ? "#fff" : t.text,
          borderRadius: 14, padding: "8px 12px", fontSize: 13.5, fontFamily: "Inter, sans-serif",
          border: isMe ? "none" : `1px solid ${t.border}`, cursor: "pointer", lineHeight: 1.5,
        }}>
          {msg.replyTo && (
            <div style={{ fontSize: 11, opacity: 0.75, borderLeft: `2px solid ${isMe ? "#fff" : t.accent}`, paddingLeft: 6, marginBottom: 4 }}>Replying to previous message</div>
          )}
          {msg.text}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 2, justifyContent: isMe ? "flex-end" : "flex-start" }}>
          <span style={{ fontSize: 10, color: t.muted, fontFamily: "Inter, sans-serif" }}>{msg.time}</span>
          {isMe && <CheckCheck size={12} color={t.accent} />}
        </div>
        {showActions && (
          <div style={{ display: "flex", gap: 10, marginTop: 4, justifyContent: isMe ? "flex-end" : "flex-start" }}>
            <button onClick={() => onReply(msg)} style={{ border: "none", background: "none", color: t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 3, fontSize: 10.5 }}><Reply size={12} /> Reply</button>
            <button onClick={() => onStar(msg)} style={{ border: "none", background: "none", color: t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 3, fontSize: 10.5 }}><Star size={12} /> Star</button>
            <button style={{ border: "none", background: "none", color: t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 3, fontSize: 10.5 }}><Forward size={12} /> Forward</button>
            <button style={{ border: "none", background: "none", color: t.muted, cursor: "pointer" }}><MoreVertical size={13} /></button>
          </div>
        )}
      </div>
    </div>
  );
}

function GroupChatTab({ t, dark, group, patients, onSend, filterPatientId, onOpenUpdate, onOpenFiles, flash }) {
  const [text, setText] = useState("");
  const [replyTo, setReplyTo] = useState(null);
  const scrollRef = useRef(null);
  const messages = filterPatientId ? group.messages.filter(m => m.patientId === filterPatientId || (m.type === "update" && m.patientId === filterPatientId)) : group.messages;

  React.useEffect(() => { scrollRef.current && (scrollRef.current.scrollTop = scrollRef.current.scrollHeight); }, [messages.length]);

  const send = () => {
    if (!text.trim()) return;
    onSend({ id: "m" + Date.now(), memberId: "you", text, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), type: "text", replyTo: replyTo?.id, patientId: filterPatientId || undefined });
    setText(""); setReplyTo(null);
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "calc(100vh - 220px)" }}>
      <div ref={scrollRef} style={{ flex: 1, overflowY: "auto", padding: "10px 14px" }}>
        {messages.length === 0 && (
          <div style={{ textAlign: "center", color: t.muted, padding: 30, fontSize: 12.5, fontFamily: "Inter, sans-serif" }}>No messages yet for this thread.</div>
        )}
        {messages.map(m => (
          <MessageBubble key={m.id} msg={m} t={t} dark={dark} patients={patients} isMe={m.memberId === "you"}
            onOpenUpdate={onOpenUpdate} onOpenFiles={onOpenFiles} onReply={setReplyTo} onStar={() => flash && flash("Message starred")} />
        ))}
      </div>
      <div style={{ borderTop: `1px solid ${t.border}`, padding: "10px 12px", background: t.surface }}>
        {replyTo && (
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", background: t.surface2, borderRadius: 10, padding: "6px 10px", marginBottom: 8 }}>
            <span style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif" }}>Replying to {replyTo.type === "text" ? (memberById(replyTo.memberId)?.name || "message") : "update"}</span>
            <button onClick={() => setReplyTo(null)} style={{ border: "none", background: "none", color: t.muted, cursor: "pointer" }}><X size={13} /></button>
          </div>
        )}
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <button onClick={() => flash && flash("Attachment picker opened")} style={{ border: "none", background: "none", color: t.accent, cursor: "pointer" }}><Paperclip size={19} /></button>
          <button onClick={() => flash && flash("Camera opened")} style={{ border: "none", background: "none", color: t.accent, cursor: "pointer" }}><Camera size={19} /></button>
          <div style={{ flex: 1, display: "flex", alignItems: "center", background: t.surface2, borderRadius: 20, padding: "8px 14px" }}>
            <input value={text} onChange={e => setText(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} placeholder="Message the team…"
              style={{ flex: 1, border: "none", outline: "none", background: "transparent", fontSize: 13.5, color: t.text, fontFamily: "Inter, sans-serif" }} />
            <Smile size={17} color={t.muted} />
          </div>
          {text.trim() ? (
            <button onClick={send} style={{ border: "none", background: t.accent, color: "#fff", borderRadius: "50%", width: 38, height: 38, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}><Send size={16} /></button>
          ) : (
            <button style={{ border: "none", background: "none", color: t.accent, cursor: "pointer" }}><Mic size={20} /></button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------- GROUP PATIENTS TAB ---------------------------------- */

function GroupPatientCard({ p, t, dark, permission, onOpen, onThread, onRemove }) {
  const s = sev[p.severity];
  return (
    <div style={{ border: `1px solid ${t.border}`, borderRadius: 16, padding: "12px 14px", marginBottom: 10, background: t.surface }}>
      <div onClick={() => onOpen(p)} style={{ display: "flex", gap: 12, cursor: "pointer" }}>
        <div style={{ width: 46, height: 46, borderRadius: "50%", background: t.accentSoft, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 14, color: t.accent, border: `2.5px solid ${s.c}`, flexShrink: 0 }}>{p.initials}</div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
            <span style={{ fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 14, color: t.text }}>{p.name}</span>
            <span style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif" }}>{p.updated}</span>
          </div>
          <div style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif" }}>{p.bed} · {p.mrn} · {p.age}{p.gender ? p.gender[0] : ""} · {p.doctor}</div>
          <div style={{ fontSize: 12.5, color: t.text, fontFamily: "Inter, sans-serif", marginTop: 3, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.dx}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 7, marginTop: 6 }}>
            <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 8px", borderRadius: 999, background: dark ? s.bgDark : s.bg, color: s.c }}>{s.label.toUpperCase()}</span>
            {p.vent && <Wind size={13} color={t.accent} />}
            {p.pressor && <Zap size={13} color={BRAND.warning} />}
            {p.dialysis && <Droplets size={13} color={BRAND.navy} />}
          </div>
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 10, paddingTop: 10, borderTop: `1px solid ${t.border}` }}>
        <PermissionBadge level={permission} />
        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={() => onThread(p)} style={{ border: "none", background: "none", color: t.accent, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><MessageCircle size={13} /> Thread</button>
          <button onClick={() => onRemove(p)} style={{ border: "none", background: "none", color: BRAND.critical, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><X size={13} /> Remove</button>
        </div>
      </div>
    </div>
  );
}

function GroupPatientsTab({ t, dark, group, patients, onOpenPatient, onThread, onAddPatient, onRemovePatient }) {
  const groupPatients = patients.filter(p => group.patientIds.includes(p.id));
  return (
    <div style={{ padding: "12px 14px 30px" }}>
      <button onClick={onAddPatient} style={{
        display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%",
        border: `1.5px dashed ${t.border}`, background: "transparent", color: t.accent, borderRadius: 14,
        padding: "10px", fontSize: 12.5, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer", marginBottom: 12,
      }}><Plus size={14} /> Add Patient to Group</button>
      {groupPatients.map(p => (
        <GroupPatientCard key={p.id} p={p} t={t} dark={dark} permission={group.permissions["you"]}
          onOpen={onOpenPatient} onThread={onThread} onRemove={onRemovePatient} />
      ))}
      {groupPatients.length === 0 && <div style={{ textAlign: "center", color: t.muted, padding: 30, fontSize: 12.5, fontFamily: "Inter, sans-serif" }}>No patients in this group yet.</div>}
    </div>
  );
}

/* ---------------------------------- GROUP TASKS TAB ---------------------------------- */

const TASK_STATUS = {
  pending: { label: "Pending", c: "#8A97AC" },
  in_progress: { label: "In Progress", c: BRAND.warning },
  completed: { label: "Completed", c: BRAND.success },
  cancelled: { label: "Cancelled", c: BRAND.critical },
};

function GroupTasksTab({ t, dark, group, patients, onCreateTask, onCycleStatus }) {
  const statuses = ["pending", "in_progress", "completed", "cancelled"];
  return (
    <div style={{ padding: "12px 14px 30px" }}>
      <button onClick={onCreateTask} style={{
        display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%",
        border: "none", background: t.accentSoft, color: t.accent, borderRadius: 14,
        padding: "10px", fontSize: 12.5, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer", marginBottom: 12,
      }}><Plus size={14} /> Create Task</button>
      {group.tasks.map(task => {
        const p = patients.find(pt => pt.id === task.patientId);
        const m = memberById(task.assigned);
        const st = TASK_STATUS[task.status];
        return (
          <div key={task.id} style={{ border: `1px solid ${t.border}`, borderRadius: 14, padding: "11px 13px", marginBottom: 8, background: t.surface }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13.5, fontWeight: 700, color: t.text, fontFamily: "Inter, sans-serif", textDecoration: task.status === "completed" ? "line-through" : "none" }}>{task.title}</div>
                <div style={{ fontSize: 11, color: t.muted, fontFamily: "Inter, sans-serif", marginTop: 2 }}>{p ? `${p.name} · ${p.bed}` : "—"} · {m ? m.name.split(" ")[0] : "Unassigned"} · Due {task.due}</div>
              </div>
              <PriorityChip priority={task.priority} />
            </div>
            <div style={{ display: "flex", gap: 6, marginTop: 8, flexWrap: "wrap" }}>
              {statuses.map(s => (
                <button key={s} onClick={() => onCycleStatus(task.id, s)} style={{
                  fontSize: 10, fontWeight: 700, padding: "3px 9px", borderRadius: 999, cursor: "pointer",
                  border: `1.5px solid ${TASK_STATUS[s].c}`, background: task.status === s ? TASK_STATUS[s].c : "transparent",
                  color: task.status === s ? "#fff" : TASK_STATUS[s].c,
                }}>{TASK_STATUS[s].label}</button>
              ))}
            </div>
          </div>
        );
      })}
      {group.tasks.length === 0 && <div style={{ textAlign: "center", color: t.muted, padding: 30, fontSize: 12.5, fontFamily: "Inter, sans-serif" }}>No tasks yet.</div>}
    </div>
  );
}
/* ---------------------------------- GROUP FILES TAB ---------------------------------- */

function fileAccess(group, isAdmin) {
  const level = group.permissions["you"];
  const viewOnly = level === "view";
  return {
    canUpload: isAdmin || !viewOnly,
    canManage: isAdmin, // replace, delete, pin, archive
    canShare: isAdmin || !viewOnly,
  };
}

function FileCard({ file, t, dark, access, onPreview, onDownload, onShare, onReplace, onPin, onArchive, onDelete, onVersions }) {
  const meta = FILE_TYPE_ICON[file.type];
  const uploader = memberById(file.uploadedBy);
  return (
    <div style={{
      border: `1.5px solid ${file.pinned ? t.accent : t.border}`, borderRadius: 16, padding: "12px 14px",
      marginBottom: 10, background: t.surface, opacity: file.archived ? 0.6 : 1,
    }}>
      <div style={{ display: "flex", gap: 12 }}>
        <div style={{ width: 42, height: 42, borderRadius: 12, background: meta.c + "1E", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <meta.icon size={20} color={meta.c} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 13.5, color: t.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              {file.title || file.name}
            </span>
            {file.pinned && <Pin size={12} color={t.accent} style={{ flexShrink: 0 }} />}
          </div>
          <div style={{ fontSize: 11, color: t.muted, fontFamily: "Inter, sans-serif", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{file.name}</div>
          {file.description && <div style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif", marginTop: 2 }}>{file.description}</div>}
          <div style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif", marginTop: 4 }}>
            {uploader ? uploader.name : "Unknown"} · {file.uploadedAt} · {file.size} · v{file.version}{file.archived ? " · Archived" : ""}
          </div>
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 10, paddingTop: 10, borderTop: `1px solid ${t.border}`, flexWrap: "wrap" }}>
        <button onClick={() => onPreview(file)} style={{ border: "none", background: "none", color: t.accent, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><Eye size={13} /> Preview</button>
        <button onClick={() => onDownload(file)} style={{ border: "none", background: "none", color: t.text, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><Download size={13} /> Download</button>
        {access.canShare && <button onClick={() => onShare(file)} style={{ border: "none", background: "none", color: t.text, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><Share2 size={13} /> Share</button>}
        {file.history.length > 0 && <button onClick={() => onVersions(file)} style={{ border: "none", background: "none", color: t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><History size={13} /> Versions</button>}
        {access.canManage && (
          <>
            <button onClick={() => onReplace(file)} style={{ border: "none", background: "none", color: t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><RotateCw size={13} /> Replace</button>
            <button onClick={() => onPin(file)} style={{ border: "none", background: "none", color: file.pinned ? t.accent : t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><Pin size={13} /> {file.pinned ? "Unpin" : "Pin"}</button>
            <button onClick={() => onArchive(file)} style={{ border: "none", background: "none", color: t.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><Archive size={13} /> {file.archived ? "Unarchive" : "Archive"}</button>
            <button onClick={() => onDelete(file)} style={{ border: "none", background: "none", color: BRAND.critical, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700 }}><Trash2 size={13} /> Delete</button>
          </>
        )}
      </div>
    </div>
  );
}

function FileUploadModal({ t, onClose, onSave, replacing }) {
  const [fileType, setFileType] = useState(replacing ? replacing.type : null);
  const [fileName, setFileName] = useState("");
  const [title, setTitle] = useState(replacing ? replacing.title : "");
  const [description, setDescription] = useState(replacing ? replacing.description : "");

  const pick = (type, method) => {
    setFileType(type);
    const ext = type === "pdf" ? "pdf" : type === "excel" ? "xlsx" : type === "word" ? "docx" : "jpg";
    setFileName(`${method === "camera" ? "Scan" : "Document"}_${new Date().toISOString().slice(0, 10)}.${ext}`);
  };

  return (
    <ModalShell t={t} onClose={onClose} title={replacing ? "Replace File" : "Upload File"} icon={replacing ? RotateCw : Upload} tall>
      {!fileName ? (
        <>
          <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
            <button onClick={() => pick(replacing ? replacing.type : "pdf", "camera")} style={{
              flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
              padding: "22px 8px", borderRadius: 18, border: `1.5px dashed ${t.border}`, background: t.surface2, cursor: "pointer",
            }}>
              <Camera size={22} color={t.accent} />
              <span style={{ fontSize: 12, fontWeight: 600, color: t.text, fontFamily: "Inter, sans-serif" }}>Take Photo</span>
            </button>
            <button onClick={() => pick(replacing ? replacing.type : "pdf", "device")} style={{
              flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
              padding: "22px 8px", borderRadius: 18, border: `1.5px dashed ${t.border}`, background: t.surface2, cursor: "pointer",
            }}>
              <Upload size={22} color={t.accent} />
              <span style={{ fontSize: 12, fontWeight: 600, color: t.text, fontFamily: "Inter, sans-serif" }}>Select File</span>
            </button>
          </div>
          {!replacing && (
            <>
              <div style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif", marginBottom: 8, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.4 }}>File type</div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {["pdf", "excel", "word", "image"].map(ty => <Chip key={ty} label={ty === "pdf" ? "PDF" : ty[0].toUpperCase() + ty.slice(1)} onClick={() => pick(ty, "device")} t={t} />)}
              </div>
            </>
          )}
        </>
      ) : (
        <>
          <div style={{ display: "flex", alignItems: "center", gap: 10, background: t.surface2, borderRadius: 14, padding: "10px 14px", marginBottom: 14 }}>
            {React.createElement(FILE_TYPE_ICON[fileType].icon, { size: 18, color: FILE_TYPE_ICON[fileType].c })}
            <span style={{ fontSize: 13, color: t.text, fontFamily: "Inter, sans-serif", fontWeight: 600 }}>{fileName}</span>
          </div>
          <div style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif", marginBottom: 6, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.4 }}>Title (optional)</div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, background: t.surface2, borderRadius: 14, padding: "10px 14px", marginBottom: 14 }}>
            <input value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. September Duty Roster"
              style={{ flex: 1, border: "none", outline: "none", background: "transparent", fontSize: 13.5, color: t.text, fontFamily: "Inter, sans-serif" }} />
          </div>
          <div style={{ fontSize: 11.5, color: t.muted, fontFamily: "Inter, sans-serif", marginBottom: 6, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.4 }}>Description (optional)</div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, background: t.surface2, borderRadius: 14, padding: "10px 14px", marginBottom: 18 }}>
            <input value={description} onChange={e => setDescription(e.target.value)} placeholder="Add a short note"
              style={{ flex: 1, border: "none", outline: "none", background: "transparent", fontSize: 13.5, color: t.text, fontFamily: "Inter, sans-serif" }} />
          </div>
          <button onClick={() => onSave({ name: fileName, type: fileType, title, description, size: `${(Math.random() * 400 + 40).toFixed(0)} KB` })} style={{
            width: "100%", padding: 14, borderRadius: 16, border: "none", background: t.accent, color: "#fff",
            fontWeight: 700, fontFamily: "Manrope, sans-serif", cursor: "pointer",
          }}>{replacing ? "Upload New Version" : "Upload File"}</button>
        </>
      )}
    </ModalShell>
  );
}

function FileVersionsModal({ t, file, onClose, onDownload }) {
  const versions = [{ version: file.version, uploadedBy: file.uploadedBy, uploadedAt: file.uploadedAt, size: file.size }, ...file.history].sort((a, b) => b.version - a.version);
  return (
    <ModalShell t={t} onClose={onClose} title={`Versions — ${file.title || file.name}`} icon={History} tall>
      {versions.map(v => {
        const u = memberById(v.uploadedBy);
        return (
          <div key={v.version} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 0", borderBottom: `1px solid ${t.border}` }}>
            <div style={{ width: 32, height: 32, borderRadius: 10, background: t.accentSoft, color: t.accent, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 12, flexShrink: 0 }}>v{v.version}</div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: t.text, fontFamily: "Inter, sans-serif" }}>{v.version === file.version ? "Current" : "Previous"} version</div>
              <div style={{ fontSize: 11, color: t.muted, fontFamily: "Inter, sans-serif" }}>{u ? u.name : "Unknown"} · {v.uploadedAt} · {v.size}</div>
            </div>
            <button onClick={() => onDownload(v)} style={{ border: "none", background: "none", color: t.accent, cursor: "pointer" }}><Download size={16} /></button>
          </div>
        );
      })}
    </ModalShell>
  );
}

function GroupFilesTab({ t, dark, group, isAdmin, onUpload, onReplace, onPin, onArchive, onDelete, flash }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState("newest");
  const [showArchived, setShowArchived] = useState(false);
  const [showUpload, setShowUpload] = useState(false);
  const [replacing, setReplacing] = useState(null);
  const [versionsFile, setVersionsFile] = useState(null);
  const access = fileAccess(group, isAdmin);

  let files = group.files.filter(f =>
    (showArchived || !f.archived) &&
    ((f.title || f.name).toLowerCase().includes(query.toLowerCase()) || f.name.toLowerCase().includes(query.toLowerCase()))
  );
  files = [...files].sort((a, b) => {
    if (sort === "name") return (a.title || a.name).localeCompare(b.title || b.name);
    if (sort === "oldest") return a.id.localeCompare(b.id);
    return b.id.localeCompare(a.id);
  });
  files.sort((a, b) => (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0));

  return (
    <div style={{ padding: "12px 14px 30px" }}>
      {access.canUpload && (
        <button onClick={() => { setReplacing(null); setShowUpload(true); }} style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%",
          border: "none", background: t.accentSoft, color: t.accent, borderRadius: 14,
          padding: "10px", fontSize: 12.5, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer", marginBottom: 12,
        }}><Upload size={14} /> Upload File</button>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 10, background: t.surface, border: `1px solid ${t.border}`, borderRadius: 14, padding: "9px 13px", marginBottom: 10 }}>
        <Search size={15} color={t.muted} />
        <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search files…"
          style={{ border: "none", outline: "none", background: "transparent", flex: 1, fontSize: 13, color: t.text, fontFamily: "Inter, sans-serif" }} />
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 12, overflowX: "auto" }}>
        <ArrowUpDown size={13} color={t.muted} style={{ flexShrink: 0 }} />
        {[["newest", "Newest"], ["oldest", "Oldest"], ["name", "Name"]].map(([k, l]) => (
          <Chip key={k} label={l} active={sort === k} onClick={() => setSort(k)} t={t} />
        ))}
        <div style={{ flex: 1 }} />
        <Chip label="Show archived" active={showArchived} onClick={() => setShowArchived(a => !a)} t={t} />
      </div>

      {files.map(f => (
        <FileCard key={f.id} file={f} t={t} dark={dark} access={access}
          onPreview={(file) => flash && flash(`Previewing ${file.name}`)}
          onDownload={(file) => flash && flash(`Downloading ${file.name}`)}
          onShare={(file) => { if (navigator.share) navigator.share({ title: file.title || file.name, text: `Shared from ${group.name}` }).catch(() => {}); else flash && flash("Shared in group"); }}
          onReplace={(file) => { setReplacing(file); setShowUpload(true); }}
          onPin={onPin} onArchive={onArchive} onDelete={onDelete}
          onVersions={(file) => setVersionsFile(file)} />
      ))}
      {files.length === 0 && <div style={{ textAlign: "center", color: t.muted, padding: 30, fontSize: 12.5, fontFamily: "Inter, sans-serif" }}>No files match.</div>}

      {showUpload && (
        <FileUploadModal t={t} replacing={replacing} onClose={() => { setShowUpload(false); setReplacing(null); }}
          onSave={(data) => { replacing ? onReplace(replacing, data) : onUpload(data); setShowUpload(false); setReplacing(null); }} />
      )}
      {versionsFile && (
        <FileVersionsModal t={t} file={versionsFile} onClose={() => setVersionsFile(null)}
          onDownload={(v) => flash && flash(`Downloading v${v.version}`)} />
      )}
    </div>
  );
}

/* ---------------------------------- GROUP MEMBERS TAB ---------------------------------- */

function GroupMembersTab({ t, dark, group, isAdmin, onChangePermission, flash }) {
  return (
    <div style={{ padding: "12px 14px 30px" }}>
      {group.memberIds.map(id => {
        const m = memberById(id);
        if (!m) return null;
        return (
          <div key={id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 0", borderBottom: `1px solid ${t.border}` }}>
            <MemberAvatar m={m} t={t} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 13.5, color: t.text }}>{m.name}</span>
                {group.owners.includes(id) && <Crown size={12} color={BRAND.critical} />}
                {group.admins.includes(id) && !group.owners.includes(id) && <UserCog size={12} color={BRAND.navy} />}
              </div>
              <div style={{ fontSize: 11, color: t.muted, fontFamily: "Inter, sans-serif" }}>{m.role} · {m.specialty}</div>
            </div>
            {isAdmin && id !== "you" ? (
              <select value={group.permissions[id] || "view"} onChange={e => onChangePermission(id, e.target.value)} style={{
                border: `1px solid ${t.border}`, borderRadius: 10, background: t.surface2, color: t.text,
                fontSize: 11, padding: "5px 7px", fontFamily: "Inter, sans-serif",
              }}>
                {Object.entries(PERMISSION_LEVELS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
              </select>
            ) : (
              <PermissionBadge level={group.permissions[id] || "view"} />
            )}
          </div>
        );
      })}
      <button onClick={() => flash && flash("Member picker opened")} style={{
        display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%",
        border: `1.5px dashed ${t.border}`, background: "transparent", color: t.accent, borderRadius: 14,
        padding: "10px", fontSize: 12.5, fontWeight: 700, fontFamily: "Inter, sans-serif", cursor: "pointer", marginTop: 12,
      }}><UserPlus size={14} /> Add Member</button>
    </div>
  );
}

/* ---------------------------------- GROUP SCREEN ---------------------------------- */

const GROUP_TABS = ["Chat", "Patients", "Files", "Tasks", "Members"];

function GroupScreen({ t, dark, group, setGroup, patients, onBack, onOpenPatient, flash }) {
  const [tab, setTab] = useState("Chat");
  const [threadPatientId, setThreadPatientId] = useState(null);
  const [showAddPatient, setShowAddPatient] = useState(false);
  const [showAddUpdate, setShowAddUpdate] = useState(false);
  const [showCreateTask, setShowCreateTask] = useState(false);
  const [showActivity, setShowActivity] = useState(false);
  const [removeCandidate, setRemoveCandidate] = useState(null);

  const isAdmin = group.admins.includes("you");

  const sendMessage = (msg) => setGroup(g => ({ ...g, messages: [...g.messages, msg] }));

  const notifyFile = (fileName, fileType, action, version) => {
    setGroup(g => ({
      ...g,
      messages: [...g.messages, {
        id: "m" + Date.now(), memberId: "system", type: "file", time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        fileName, fileType, action, version, by: "Dr. Sarah Nassar",
      }],
    }));
  };

  const uploadFile = (data) => {
    const id = "f" + Date.now();
    setGroup(g => ({
      ...g,
      files: [...g.files, {
        id, name: data.name, title: data.title, description: data.description, type: data.type,
        size: data.size, uploadedBy: "you", uploadedAt: "Just now", pinned: false, archived: false, version: 1, history: [],
      }],
    }));
    notifyFile(data.title || data.name, data.type, "uploaded", 1);
    flash && flash("File uploaded");
  };

  const replaceFile = (file, data) => {
    setGroup(g => ({
      ...g,
      files: g.files.map(f => f.id !== file.id ? f : {
        ...f, name: data.name, title: data.title, description: data.description, size: data.size,
        uploadedBy: "you", uploadedAt: "Just now", version: f.version + 1,
        history: [{ version: f.version, uploadedBy: f.uploadedBy, uploadedAt: f.uploadedAt, size: f.size }, ...f.history],
      }),
    }));
    notifyFile(data.title || data.name, file.type, "replaced", file.version + 1);
    flash && flash("New version uploaded");
  };

  const pinFile = (file) => setGroup(g => ({ ...g, files: g.files.map(f => f.id === file.id ? { ...f, pinned: !f.pinned } : f) }));
  const archiveFile = (file) => setGroup(g => ({ ...g, files: g.files.map(f => f.id === file.id ? { ...f, archived: !f.archived } : f) }));
  const deleteFile = (file) => { setGroup(g => ({ ...g, files: g.files.filter(f => f.id !== file.id) })); flash && flash("File deleted"); };

  const addPatientToGroup = (p, silent) => {
    setGroup(g => g.patientIds.includes(p.id) ? g : {
      ...g, patientIds: [...g.patientIds, p.id],
      permissions: { ...g.permissions },
    });
    if (!silent) { flash && flash(`${p.name} added to ${group.name}`); setShowAddPatient(false); }
  };

  const removePatient = () => {
    setGroup(g => ({ ...g, patientIds: g.patientIds.filter(id => id !== removeCandidate.id) }));
    flash && flash(`${removeCandidate.name} removed — history archived`);
    setRemoveCandidate(null);
  };

  const saveUpdate = (data) => {
    const p = patients.find(pt => pt.id === data.patientId);
    const doctorName = "Dr. Sarah Nassar";
    setGroup(g => ({
      ...g,
      messages: [...g.messages, {
        id: "m" + Date.now(), memberId: "system", type: "update", time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        patientId: data.patientId, updateType: data.updateType, by: doctorName,
      }],
    }));
    setShowAddUpdate(false);
    setTab("Chat");
  };

  const createTask = (task) => {
    setGroup(g => ({ ...g, tasks: [...g.tasks, { id: "t" + Date.now(), ...task }] }));
    setShowCreateTask(false);
    flash && flash("Task created");
  };
  const cycleTaskStatus = (taskId, status) => setGroup(g => ({ ...g, tasks: g.tasks.map(t2 => t2.id === taskId ? { ...t2, status } : t2) }));
  const changePermission = (memberId, level) => setGroup(g => ({ ...g, permissions: { ...g.permissions, [memberId]: level } }));

  if (threadPatientId) {
    const p = patients.find(pt => pt.id === threadPatientId);
    return (
      <div style={{ position: "fixed", inset: 0, zIndex: 62, background: t.bg, maxWidth: 480, margin: "0 auto", display: "flex", flexDirection: "column" }}>
        <div style={{ padding: "16px 12px 10px", display: "flex", alignItems: "center", gap: 10, borderBottom: `1px solid ${t.border}` }}>
          <IconBtn icon={ChevronLeft} onClick={() => setThreadPatientId(null)} t={t} />
          <div style={{ width: 34, height: 34, borderRadius: "50%", background: t.accentSoft, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 12, color: t.accent, flexShrink: 0 }}>{p?.initials}</div>
          <div>
            <div style={{ fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 14.5, color: t.text }}>{p?.bed} — {p?.name}</div>
            <div style={{ fontSize: 11, color: t.muted, fontFamily: "Inter, sans-serif" }}>Patient thread · {group.name}</div>
          </div>
        </div>
        <GroupChatTab t={t} dark={dark} group={group} patients={patients} onSend={sendMessage}
          filterPatientId={threadPatientId} onOpenUpdate={onOpenPatient} onOpenFiles={() => {}} flash={flash} />
      </div>
    );
  }

  return (
    <div style={{ paddingBottom: 4 }}>
      <div style={{ padding: "16px 12px 10px", display: "flex", alignItems: "center", gap: 10 }}>
        <IconBtn icon={ChevronLeft} onClick={onBack} t={t} />
        <GroupAvatar group={group} size={38} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 15, color: t.text }}>{group.name}</div>
          <div style={{ fontSize: 10.5, color: t.muted, fontFamily: "Inter, sans-serif", display: "flex", alignItems: "center", gap: 4 }}>
            <ShieldCheck size={10} /> Encrypted · {group.memberIds.length} members · {group.patientIds.length} patients
          </div>
        </div>
        {isAdmin && <IconBtn icon={History} onClick={() => setShowActivity(true)} t={t} />}
      </div>

      <div style={{ display: "flex", gap: 6, padding: "4px 12px 10px", overflowX: "auto" }}>
        {GROUP_TABS.map(tb => <Chip key={tb} label={tb} active={tab === tb} onClick={() => setTab(tb)} t={t} />)}
      </div>

      <div style={{ display: "flex", gap: 6, padding: "0 12px 10px", overflowX: "auto" }}>
        <button onClick={() => setShowAddPatient(true)} style={{ display: "flex", alignItems: "center", gap: 4, border: "none", background: t.surface2, color: t.text, borderRadius: 999, padding: "6px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}><Plus size={11} /> Add Patient</button>
        <button onClick={() => setShowAddUpdate(true)} style={{ display: "flex", alignItems: "center", gap: 4, border: "none", background: t.surface2, color: t.text, borderRadius: 999, padding: "6px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}><Sparkles size={11} /> Add Patient Update</button>
        <button onClick={() => setShowCreateTask(true)} style={{ display: "flex", alignItems: "center", gap: 4, border: "none", background: t.surface2, color: t.text, borderRadius: 999, padding: "6px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}><ListChecks size={11} /> Create Task</button>
        <button onClick={() => flash && flash("Handover shared to group")} style={{ display: "flex", alignItems: "center", gap: 4, border: "none", background: t.surface2, color: t.text, borderRadius: 999, padding: "6px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}><FileDown size={11} /> Share Handover</button>
        <button onClick={() => flash && flash("Group summary generated")} style={{ display: "flex", alignItems: "center", gap: 4, border: "none", background: t.surface2, color: t.text, borderRadius: 999, padding: "6px 11px", fontSize: 10.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}><Sparkles size={11} /> Group Summary</button>
      </div>

      {tab === "Chat" && <GroupChatTab t={t} dark={dark} group={group} patients={patients} onSend={sendMessage} filterPatientId={null} onOpenUpdate={onOpenPatient} onOpenFiles={() => setTab("Files")} flash={flash} />}
      {tab === "Patients" && (
        <GroupPatientsTab t={t} dark={dark} group={group} patients={patients} onOpenPatient={onOpenPatient}
          onThread={(p) => setThreadPatientId(p.id)} onAddPatient={() => setShowAddPatient(true)} onRemovePatient={setRemoveCandidate} />
      )}
      {tab === "Files" && (
        <GroupFilesTab t={t} dark={dark} group={group} isAdmin={isAdmin}
          onUpload={uploadFile} onReplace={replaceFile} onPin={pinFile} onArchive={archiveFile} onDelete={deleteFile} flash={flash} />
      )}
      {tab === "Tasks" && <GroupTasksTab t={t} dark={dark} group={group} patients={patients} onCreateTask={() => setShowCreateTask(true)} onCycleStatus={cycleTaskStatus} />}
      {tab === "Members" && <GroupMembersTab t={t} dark={dark} group={group} isAdmin={isAdmin} onChangePermission={changePermission} flash={flash} />}

      {showAddPatient && (
        <AddPatientToGroupModal t={t} dark={dark} patients={patients} group={group}
          onClose={() => setShowAddPatient(false)} onAdd={addPatientToGroup} flash={flash} />
      )}
      {showAddUpdate && (
        <AddPatientUpdateFlow t={t} dark={dark} group={group} patients={patients}
          onClose={() => setShowAddUpdate(false)} onSave={saveUpdate} flash={flash} />
      )}
      {showCreateTask && (
        <CreateTaskModal t={t} group={group} patients={patients} onClose={() => setShowCreateTask(false)} onCreate={createTask} />
      )}
      {showActivity && <GroupActivityModal t={t} group={group} patients={patients} onClose={() => setShowActivity(false)} />}

      {removeCandidate && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.5)", display: "flex", alignItems: "flex-end", zIndex: 70 }} onClick={() => setRemoveCandidate(null)}>
          <div onClick={e => e.stopPropagation()} style={{ background: t.surface, width: "100%", maxWidth: 480, margin: "0 auto", borderRadius: "24px 24px 0 0", padding: 22 }}>
            <div style={{ fontFamily: "Manrope, sans-serif", fontWeight: 800, fontSize: 16, color: t.text, marginBottom: 10 }}>Remove Patient</div>
            <div style={{ fontSize: 13, color: t.muted, fontFamily: "Inter, sans-serif", lineHeight: 1.6, marginBottom: 18 }}>
              Remove {removeCandidate.name} from {group.name}? Previous messages, updates, tasks, and audit history will remain securely archived.
            </div>
            <div style={{ display: "flex", gap: 10 }}>
              <button onClick={() => setRemoveCandidate(null)} style={{ flex: 1, padding: 13, borderRadius: 14, border: `1.5px solid ${t.border}`, background: "transparent", color: t.text, fontWeight: 700, fontFamily: "Manrope, sans-serif", cursor: "pointer" }}>Cancel</button>
              <button onClick={removePatient} style={{ flex: 1, padding: 13, borderRadius: 14, border: "none", background: BRAND.critical, color: "#fff", fontWeight: 700, fontFamily: "Manrope, sans-serif", cursor: "pointer" }}>Remove</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

